    $hexAttributes = $interactionState->apply(
        $attributes
            ->class($hexClasses)
            ->merge([
                'type' => 'text',
                'data-color-picker-hex' => true,
                'value' => strtoupper($currentValue),
                'placeholder' => $placeholderText,
                'spellcheck' => 'false',
                'inputmode' => 'text',
                'autocomplete' => 'off',
                'aria-label' => __('stencil-ui::messages.color_picker_hex'),
                'aria-expanded' => 'false',
            ]),
        ['nativeDisabled' => true],
    );

